package cn.balltv.portal;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.util.*;import javax.crypto.*;import javax.crypto.spec.*;import java.net.URLEncoder;
public class RoomSourcesTest {
 private JSONObject room()throws Exception{return new JSONObject("{anchorid:1,category_id:2,title:'甲 VS 乙',ticket:0,price:0,room_type:0,reply_video:0,match_id:90,anchor_name:'主播'}");}
 @Test public void paidPrivateReplayAndOfflineRoomsAreFiltered()throws Exception{assertTrue(RoomSources.allowed(room()));for(String key:new String[]{"ticket","price","room_type","isvideo","reply_video","animation","end_stamp"})assertFalse(key,RoomSources.allowed(room().put(key,1)));assertFalse(RoomSources.allowed(room().put("password","secret")));assertFalse(RoomSources.allowed(room().put("status",0)));assertFalse(RoomSources.allowed(room().put("islive",0)));}
 @Test public void nonSportsAndPromotionalTitlesAreFiltered()throws Exception{assertFalse(RoomSources.allowed(room().put("category_id",100)));assertFalse(RoomSources.allowed(room().put("title","甲VS乙 充值送彩金")));assertFalse(RoomSources.allowed(room().put("title","甲VS乙 回放")));assertFalse(RoomSources.allowed(room().put("anchorid","")));}
 @Test public void actualMatchGroupsAnchorsButUnrelatedMetadataDoesNot()throws Exception{JSONArray rooms=new JSONArray().put(room()).put(room().put("anchorid",2));JSONArray events=new JSONArray("[{id:90,home_team_name_zh:'甲',away_team_name_zh:'乙',time:1794214800,home_score:2,away_score:1}]");List<Feeds.Match> list=RoomSources.parse(RoomSources.LONGMEN,rooms,events);assertEquals(1,list.size());assertFalse(list.get(0).estimated);assertEquals(2,list.get(0).raw.getJSONObject("extra").getJSONArray("rooms").length());events.getJSONObject(0).put("home_team_name_zh","丙");list=RoomSources.parse(RoomSources.LONGMEN,rooms,events);assertEquals(2,list.size());assertTrue(list.get(0).estimated);assertEquals("",list.get(0).time);}
 @Test public void publicWrapperRoundTripDoesNotIncludeVideoInMatchRecord()throws Exception{String suffix="1234abcd",raw="[{anchorid:1}]";Cipher c=Cipher.getInstance("AES/CBC/PKCS5Padding");c.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(("ADKOPSTF%2003.40.51.jpeg"+suffix).getBytes("UTF-8"),"AES"),new IvParameterSpec("ADKOPSTF%2003.40".getBytes("UTF-8")));String wrapper=URLEncoder.encode(Base64.getEncoder().encodeToString(c.doFinal(raw.getBytes("UTF-8"))),"UTF-8")+suffix;assertEquals(1,((JSONArray)RoomSources.decode(wrapper)).getJSONObject(0).getInt("anchorid"));List<Feeds.Match> list=RoomSources.parse(RoomSources.LONGMEN,new JSONArray().put(room().put("pull_url","https://example.org/live.flv?token=private")),new JSONArray());assertFalse(list.get(0).raw.toString().contains("token=private"));}
 @Test(expected=Exception.class) public void malformedWrapperIsRejected()throws Exception{RoomSources.decode("short");}
 @Test public void capabilitiesDoNotClaimMissingSchedulesOrReplays(){for(String s:new String[]{RoomSources.LONGMEN,RoomSources.JINGYU}){assertTrue(SourceCatalog.supports(s,"live"));assertFalse(SourceCatalog.supports(s,"schedule"));assertFalse(SourceCatalog.supports(s,"replay"));}assertTrue(SourceCatalog.supports(ExtraSources.SOMI,"schedule"));}
}
